"use client";

import { type AnchorHTMLAttributes, type HTMLAttributes, type Ref, useRef } from "react";
import { useIndicator } from "../interaction/hooks";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

/**
 * Sibling pages as text tabs. These are links (navigation), not an ARIA tablist; see Tabs for panels. The underline
 * slides to the current page when it changes (as long as the tabs stay mounted across navigation, as they do in a shared
 * layout), and it is placed without sliding on first paint.
 */
export function PageTabs({ className, ...rest }: HTMLAttributes<HTMLElement> & { "aria-label": string }) {
  const ref = useRef<HTMLElement>(null);
  useIndicator(ref, { item: ".hm-page-tab", active: '.hm-page-tab[aria-current="page"]' });
  return <nav {...rest} ref={ref} className={cx("hm-page-tabs", className)} />;
}

export function PageTab({
  current,
  asChild,
  className,
  ...rest
}: AnchorHTMLAttributes<HTMLAnchorElement> & { current?: boolean; asChild?: boolean; ref?: Ref<HTMLAnchorElement> }) {
  const Comp = asChild ? Slot : "a";
  return (
    <Comp {...(rest as object)} className={cx("hm-page-tab", className)} aria-current={current ? "page" : undefined} />
  );
}
